/**
 * opensim-replay — run the engine on postures generated by the OpenSim model
 * (validation/opensim/export_postures.py) and report, per posture, how often
 * the expected metric fires and how often a metric that should stay quiet
 * fires (cross-talk), for the shipped engine and for switch sets.
 *
 *   node scripts/opensim-replay.mjs                 # table: shipped vs camp
 *   node scripts/opensim-replay.mjs --exp edge,trunklean
 *   node scripts/opensim-replay.mjs --json out.json
 *
 * Synthetic, from a kinematic fixture: it tests the engine's geometry and the
 * consistency of its findings, not clinical accuracy (CLAUDE.md). The camera
 * projection is the engine fixture's own (syntheticSubject.projectToLandmarks).
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { analyzeMP, resetProportions } from "../src/features/analysis/postureEngine.js";
import { projectToLandmarks, DEFAULT_BODY } from "../src/features/analysis/syntheticSubject.mjs";
import { createSlumpTracker, slumpMetric } from "../src/features/analysis/slumpModel.js";

const here = dirname(fileURLToPath(import.meta.url));
const DATA = resolve(here, "../../validation/opensim/postures.json");
const W = 1280, H = 720;

export const CAMERAS = [
  { id: "near", distCm: 45, heightCm: 8 },
  { id: "mid",  distCm: 60, heightCm: 5 },
  { id: "far",  distCm: 80, heightCm: 0 },
];
export const SWITCH_SETS = {
  shipped: [],
  camp: ["edge", "fhpguard", "trunklean", "modcap", "head3d", "tiltguard", "slump"],
};
const BODY_TORSO = { mid: 1, small: 0.9, large: 1.08, longneck: 1, eyes_high: 1, eyes_low: 1 };

function rng(seed) { return () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const gauss = r => Math.sqrt(-2 * Math.log(r() || 1e-9)) * Math.cos(2 * Math.PI * r());

function extFor(exp, truthPitchDeg, r) {
  let ext = null;
  const add = o => { ext = { ...(ext || {}), ...o }; };
  // head3d needs the face model's pitch. Stand-in: true pitch + 2° noise.
  if (exp.includes("head3d")) add({ head: { pitchDeg: truthPitchDeg + 2 * gauss(r), neutralDeg: null }, moderateCap: true });
  if (exp.includes("edge")) add({ edgeGuard: true });
  if (exp.includes("fhpguard")) add({ fhpGuard: true });
  if (exp.includes("trunklean")) add({ trunkLean: true });
  if (exp.includes("modcap")) add({ moderateCap: true });
  if (exp.includes("tiltguard")) add({ tiltGuard: true });
  return ext;
}

function toLms(points, cam, body, r, noise = 0.0025) {
  const pts = {};
  for (const [i, p] of Object.entries(points)) pts[i] = { x: p[0], y: p[1], z: p[2] };
  const lms = projectToLandmarks(pts, cam, body);
  return lms.map(l => l && l.visibility > 0 ? { ...l, x: l.x + noise * gauss(r), y: l.y + noise * gauss(r) } : l);
}

const pitchOf = c => -((c.neck_rz || 0) + (c.head_rz || 0) + (c.lumbar_rz || 0) * 0 ) * 180 / Math.PI;

export function runCase(data, posture, bodyId, cam, exp, seed = 1) {
  const neutral = data.postures.find(p => p.id === "neutral");
  const body = { ...DEFAULT_BODY, torsoLenCm: DEFAULT_BODY.torsoLenCm * (BODY_TORSO[bodyId] ?? 1) };
  const r = rng(seed);
  resetProportions();
  let t = Date.now(); analyzeMP.__testNowMs = t;
  let res = null;
  const slump = exp.includes("slump") ? createSlumpTracker() : null;
  const frame = (pts, pitch) => { t += 50; analyzeMP.__testNowMs = t;
    const lms = toLms(pts, cam, body, r);
    res = analyzeMP(lms, W, H, "front", null, null, null, null, extFor(exp, pitch, r));
    // As in App.jsx: the learned layer runs beside the engine.
    if (slump) { const sm = slumpMetric(slump.update(lms, W, H), { learning: slump.learning }); if (sm) res = { ...res, metrics: { ...res.metrics, slump_posture: sm } }; } };
  for (let i = 0; i < 130; i++) frame(neutral.bodies[bodyId], 0);
  for (let i = 0; i < 60; i++) frame(posture.bodies[bodyId], pitchOf(posture.coords));
  analyzeMP.__testNowMs = null;
  return res;
}

const fired = m => m && m.reliable !== false && m.severity && m.severity !== "normal";

export function evaluate(data, exp) {
  const rows = [];
  for (const p of data.postures) {
    let hit = 0, n = 0, cross = 0, crossN = 0, scoreSum = 0; const crossBy = {};
    for (const b of data.bodies) for (const cam of CAMERAS) {
      const r = runCase(data, p, b, cam, exp, n + 7);
      const m = r?.metrics || {};
      n++; scoreSum += r?.score ?? 0;
      if (p.expect.every(group => group.split("|").some(k => fired(m[k])))) hit++;
      for (const k of p.clean) { crossN++; if (fired(m[k])) { cross++; crossBy[k] = (crossBy[k] || 0) + 1; } }
    }
    rows.push({ id: p.id, hit: p.expect.length ? hit / n : null, cross: crossN ? cross / crossN : 0, score: Math.round(scoreSum / n), crossBy });
  }
  return rows;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const args = process.argv.slice(2);
  const data = JSON.parse(readFileSync(DATA, "utf8"));
  const expArg = args.includes("--exp") ? args[args.indexOf("--exp") + 1].split(",") : null;
  const sets = expArg ? { shipped: [], [expArg.join("+")]: expArg } : SWITCH_SETS;
  const results = Object.fromEntries(Object.entries(sets).map(([k, e]) => [k, evaluate(data, e)]));
  const names = Object.keys(results);
  const pct = x => x == null ? "  – " : String(Math.round(x * 100)).padStart(3) + "%";
  console.log(`\nOpenSim fixture: ${data.postures.length} postures × ${data.bodies.length} bodies × ${CAMERAS.length} cameras (OpenSim ${data.opensim})`);
  console.log("posture".padEnd(18) + names.map(n => `| ${n.padEnd(22)}`).join(""));
  console.log(" ".repeat(18) + names.map(() => "| caught  cross  score  ").join(""));
  for (let i = 0; i < data.postures.length; i++) {
    console.log(results[names[0]][i].id.padEnd(18) + names.map(n => { const r = results[n][i];
      return `|  ${pct(r.hit)}   ${pct(r.cross)}   ${String(r.score).padStart(3)}   `; }).join(""));
  }
  if (args.includes("--detail")) for (const n of names) { console.log(`\ncross-talk by metric (${n}):`);
    for (const r of results[n]) if (Object.keys(r.crossBy).length) console.log(`  ${r.id.padEnd(18)} ${JSON.stringify(r.crossBy)}`); }
  if (args.includes("--json")) writeFileSync(args[args.indexOf("--json") + 1], JSON.stringify(results, null, 1));
  if (args.includes("--check")) {
    // Regression checks for the fixes this fixture found (npm run test:opensim).
    const row = (set, id) => results[set].find(r => r.id === id);
    const checks = [
      ["tiltguard: a head tilt does not read as a shrug", (row("camp", "head_tilt_r_15").crossBy.shoulder_elevation || 0) === 0],
      ["trunklean: a trunk lean is still caught", row("camp", "trunk_lean_r_10").hit === 1],
      ["slump: no slumped-posture finding at neutral", !row("camp", "neutral").crossBy.slump_posture],
      ["slump: no slumped-posture finding on head tilt / turn / shrug", ["head_tilt_r_15", "head_turn_l_30", "shrug_both"].every(id => !row("camp", id).crossBy.slump_posture)],
      ["slump: the sofa recline is caught in most bodies and cameras", row("camp", "recline_slump").hit >= 0.8],
      ["camp switches: neutral cross-talk stays low", row("camp", "neutral").cross <= 0.05],
    ];
    let fail = 0;
    console.log("");
    for (const [name, ok] of checks) { console.log(`  ${ok ? "ok  " : "FAIL"}  ${name}`); if (!ok) fail++; }
    console.log(`\n${checks.length - fail} passed · ${fail} failed`);
    if (fail) process.exit(1);
  }
}
